When $\mathcal{S}'=\mathcal{S}$, we set $End(\mathcal{S})\stackrel{{\rm def.}}{=}
Hom(\mathcal{S},\mathcal{S})$, $Aut(\mathcal{S})\stackrel{{\rm def.}}{=} Isom(\mathcal{S},\mathcal{S})$ and $\mathrm{End}(\mathcal{S})\stackrel{{\rm def.}}{=}
{\rm Hom}(\mathcal{S},\mathcal{S})$, $\mathrm{Aut}(\mathcal{S})\stackrel{{\rm def.}}{=} \mathrm{Isom}(\mathcal{S},\mathcal{S})$.

When $W=TM$ is the tangent bundle of a manifold $M$,
we set $\mathrm{Met}_{p,q}(M)\stackrel{{\rm def.}}{=} \mathrm{Met}_{p,q}(TM)$ and $\mathrm{Met}(M)\stackrel{{\rm def.}}{=}
\mathrm{Met}(TM)$.

The
{\em curvature} $\mathcal{F}\in \Omega^2(E,V)$ of $H$ is defined
as \cite{Michor}:
\begin{equation*}
\mathcal{F}(X,Y)\stackrel{{\rm def.}}{=} [X_H,Y_H]_V\, , \quad \forall X,Y\in \mathcal{X}(E)\, .
\end{equation*}

Its restriction to $H$ gives a section
$\mathcal{F}_H\in \Gamma(E,\wedge^2H^\ast\otimes V)$ which satisfies:
\begin{equation*}
\mathcal{F}_H(X,Y)=\mathcal{F}(X,Y)=[X,Y]_V\, , \quad \forall X,Y\in \Gamma(E,H)
\end{equation*}
and hence coincides up to a constant factor with the restriction to
$H$ of O'Neill's second fundamental tensor $A$ \cite{ONeill} of the
pseudo-Riemannian submersion $\pi$:
\begin{equation*}
A_XY=-A_YX=\frac{1}{2}\mathcal{F}_H(X,Y)\, , \quad \forall X,Y\in \Gamma(E,H)~~.
\end{equation*}

Let:
\begin{equation*}
G\stackrel{{\rm def.}}{=} \{T_\gamma\, , \,\, |\,\, \gamma\in \mathcal{P}(M)\, , \quad \gamma(0)=\gamma(1)=m_0\}\subseteq \mathrm{Iso}(\mathcal{M},\mathcal{G})
\end{equation*}
be the Ehresmann holonomy group at $m_0$.

The $T$-invariance of $\mathbf{\Phi}$ means that the restrictions
$\Phi_m\stackrel{{\rm def.}}{=} \mathbf{\Phi}|_{E_m}\in \mathcal{C}^\infty(E_m,\mathbb{R})$ to the fibers of $E$
satisfy:
\begin{equation*}
\Phi_{\gamma(1)}\circ T_\gamma=\Phi_{\gamma(0)}\, ,\quad \forall\,\, \gamma\in \mathcal{P}(M)~~, 
\end{equation*}
a condition which is equivalent with the requirement that $\mathbf{\Phi}$ is
annihilated by any horizontal vector field defined on $E$:
\begin{equation} X(\mathbf{\Phi})=0\, , \quad \forall\, X\in \Gamma(E,H)\, .
\end{equation}

The holonomy group $G_{m}\subset \mathrm{Iso}(E_{m},h_{m})$ of $\pi$
at any point $m\in M$ preserves $\Phi_{m}$:
\begin{equation*}
G_m \subset \mathrm{Iso}(E_m, h_m, \Phi_m)\stackrel{{\rm def.}}{=} \{\varphi\in \mathrm{Iso}(E_m,h_m)|\Phi_m\circ \varphi=\Phi_m\}~~.
\end{equation*}

Since $H$ and $V$ are $h$-orthogonal, this implies
that the gradient of $\mathbf{\Phi}$ is a vertical vector field:
\begin{equation*}
\mathrm{grad}_h \mathbf{\Phi}\in \Gamma(E,V)~~.
\end{equation*}

Integrable scalar bundles defined over $(M,g)$ and having type
$(\mathcal{M},\mathcal{G},\Phi)$ are classified up to isomorphism by the points of the
character variety:
\begin{equation*}
\mathcal{M}_{\mathrm{Iso}(\mathcal{M},\mathcal{G},\Phi)}(M)\stackrel{{\rm def.}}{=} {\rm Hom}(\pi_1(M),\mathrm{Iso}(\mathcal{M},\mathcal{G},\Phi))/\mathrm{Iso}(\mathcal{M},\mathcal{G},\Phi)~~.
\end{equation*}

For any
$\alpha\in I$, let $g_\alpha \stackrel{{\rm def.}}{=} g|_{U_\alpha}$, $E_{\alpha} \stackrel{{\rm def.}}{=}
E|_{U_\alpha}$, $\pi_\alpha \stackrel{{\rm def.}}{=} \pi|_{U_\alpha}$.

The maps $q_\alpha$ are diffeomorphisms from $E_\alpha$ to
$E^0_{\alpha}=U_\alpha\times\mathcal{M}$ which fit into the following
commutative diagram:
\begin{equation} \scalebox{1.2}{
	\xymatrix{
		E_\alpha ~~\ar[d]_{\pi_\alpha} \ar[r]^{\!\!\!\!\!\!q_\alpha} & ~~E^0_{\alpha} \ar[d]^{\pi^0_{\alpha}}\\
		U_\alpha  \ar[r]^{\mathrm{id}_{U_\alpha}} & U_\alpha \\
	}}
\end{equation}

\scalebox{1.2}{
	\xymatrix{
		E_\alpha ~~\ar[d]_{\pi_\alpha} \ar[r]^{\!\!\!\!\!\!q_\alpha} & ~~E^0_{\alpha} \ar[d]^{\pi^0_{\alpha}}\\
		U_\alpha  \ar[r]^{\mathrm{id}_{U_\alpha}} & U_\alpha \\
	}}

For any $\alpha,\beta\in I$ such that $U_{\alpha\beta}\stackrel{{\rm def.}}{=}
U_\alpha\cap U_\beta\neq \emptyset$, we have:
\begin{equation*}
(q_\beta\circ q_\alpha^{-1})(m,p)=(m, \mathbf{g}_{\alpha\beta}(m)(p))\, , \quad \forall\, m\in U_{\alpha\beta}\, , \quad \forall\, p\in \mathcal{M}\, ,
\end{equation*}
where the transition functions $\mathbf{g}_{\alpha\beta}:U_{\alpha\beta}\rightarrow \mathrm{Iso}(\mathcal{M},\mathcal{G})$ are given by:
\begin{equation} \mathbf{g}_{\alpha\beta}(m)\stackrel{{\rm def.}}{=} {\hat q}_\beta(m)\circ {\hat q}^{-1}_\alpha(m)\in \mathrm{Iso}(\mathcal{M},\mathcal{G})\, , \quad \forall\, m\in U_{\alpha\beta}\, .
\end{equation}

Using \eqref{hatqalpha}, this gives:
\begin{equation*}
\mathbf{g}_{\alpha\beta}(m)=T_{\lambda^{\beta}}\circ T_{\gamma^{\beta}_{m}}\circ T_{\gamma^{\alpha}_{m}}^{-1}\circ T_{\lambda^{\alpha}}^{-1}=
T_{c^{\alpha\beta}_m}\in \mathrm{Iso}(\mathcal{M},\mathcal{G})\, , \quad \forall\, m\in U_{\alpha\beta}\, .
\end{equation*}

The {\em vertical Lagrange density} of $\pi$ is the map
$e^v_\Phi:\Gamma(\pi)\rightarrow \mathcal{C}^\infty(M,\mathbb{R})$ defined, for every
$s\in \Gamma(\pi)$, as follows:
\begin{equation*}
e^v_\mathbf{\Phi}(g,h,s)\stackrel{{\rm def.}}{=} \frac{1}{2}\mathrm{Tr}_{g} s^\ast_v(h_V)+\mathbf{\Phi}^s~~,
\end{equation*} 
where $s^\ast_v(h_V)$ is the vertical first fundamental form of $s$
(see Appendix \ref{app:submersions}) and $\mathbf{\Phi}^s= \mathbf{\Phi}\circ s\in
\mathcal{C}^\infty(M,\mathbb{R})$. Let:
\begin{equation*}
e^v(g,h,s)\stackrel{{\rm def.}}{=} e^v_0(g,h,s)=\frac{1}{2}\mathrm{Tr}_{g} s^\ast(h_V)~~.
\end{equation*}

Let
$\mathrm{graph}\colon \mathcal{C}^\infty(M,\mathcal{M})\rightarrow \Gamma(\pi^0)$ be the
bijective map given by:
\begin{equation*}
\mathrm{graph}(\varphi)(m)\stackrel{{\rm def.}}{=} (m,\varphi(m))~~\forall m\in M~~,
\end{equation*}
whose inverse is the map $\mathrm{ungraph}:\Gamma(\pi^0)\rightarrow \Gamma(\pi^0)$ given by:
\begin{equation*}
\mathrm{ungraph}(s^0)\stackrel{{\rm def.}}{=} p^0\circ s^0\, .
\end{equation*}

Composing the first relation from the left with $p^0_{\alpha}$ gives:
\begin{equation*}
\varphi^{\alpha}={\hat q}_\alpha\circ s_\alpha~~.
\end{equation*}

Let $\mathrm{Conf}_\mathcal{M}^{\alpha}\stackrel{{\rm def.}}{=} \mathrm{Conf}_\mathcal{M}|_{U_\alpha}$,
$\mathrm{Sol}^{g,{\alpha}}_{\mathcal{M},\mathcal{G},\Phi}\stackrel{{\rm def.}}{=}
\mathrm{Sol}^g_{\mathcal{M},\mathcal{G},\Phi}|_{U_\alpha}$ and
$\mathfrak{g}_{\alpha\beta}:\mathrm{Conf}_\mathcal{M}^{\alpha}|_{U_{\alpha\beta}}\rightarrow\mathrm{Conf}_\mathcal{M}^{\beta}|_{U_{\alpha\beta}}$
be the isomorphism of sheaves defined through:
\begin{equation*}
\mathfrak{g}_{\alpha\beta}(s) \stackrel{{\rm def.}}{=} \mathbf{g}_{\alpha\beta} s\, ,\quad  \,\, \forall\, U\subset U_{\alpha\beta}\, , \quad \forall s\in \mathrm{Conf}_\mathcal{M}^{\alpha}(U)~~.
\end{equation*}

These isomorphisms
of sheaves satisfy the cocycle conditions:
\begin{equation*}
\mathfrak{g}_{\beta\gamma}\mathfrak{g}_{\alpha\beta}=\mathfrak{g}_{\alpha\gamma}\, , \quad\forall \alpha,\beta,\gamma\in I\, . 
\end{equation*}

Clearly $\mathbf{T}_\gamma$ is an isomorphism of flat symplectic vector bundles:
\begin{equation*}
\mathbf{T}_\gamma\colon (\mathcal{S}_{\gamma(0)},D_{\gamma(0)},\omega_{\gamma(0)})\xrightarrow{\sim}(\mathcal{S}_{\gamma(1)},D_{\gamma(1)},\omega_{\gamma(1)})\, ,
\end{equation*}
which lifts the isometry $T_\gamma:(E_{\gamma(0)}, h_{\gamma(0)})\rightarrow	(E_{\gamma(1)}, h_{\gamma(1)})$.

Recall that a \emph{taming}
$\mathbf{J}\in\mathrm{Aut}(\boldsymbol{\mathcal{S}},\boldsymbol{\omega})$ is an automorphism of the symplectic vector
bundle $(\boldsymbol{\mathcal{S}},\boldsymbol{\omega})$ satisfying \cite{DuffSalamon}:
\begin{equation*}
\mathbf{J}^{2} = -\mathrm{Id}_{\boldsymbol{\mathcal{S}}}\, , \qquad \boldsymbol{\omega}(\mathbf{J} e, e) >0\, , \qquad \forall e\in \Gamma(E,\boldsymbol{\mathcal{S}})\, .
\end{equation*}

A taming $\mathbf{J}$ of $(\boldsymbol{\mathcal{S}},\boldsymbol{\omega},\mathbf{D})$ is called {\em vertical} if it
is $\mathbf{T}$-invariant, which means that it satisfies:
\begin{equation*}
\mathbf{T}_{\gamma}\circ J_{\gamma(0)}=J_{\gamma(1)}\circ \mathbf{T}_\gamma\, , \qquad \forall\, \gamma\in \mathcal{P}(M)\, .
\end{equation*}

It is clear that $\mathbf{J}$ is vertical if and only if it satisfies: 
\begin{equation*}
\mathbf{D}_X\circ\mathbf{J}=\mathbf{J}\circ \mathbf{D}_X\, ,\qquad \forall\, X\in \Gamma(E,H)\, .
\end{equation*}

In this case, $\mathbf{T}_\gamma$ is an isomorphism of tamed flat symplectic vector bundles:
\begin{equation*}
\mathbf{T}_\gamma\colon (\mathcal{S}_{\gamma(0)},\omega_{\gamma(0)},D_{\gamma(0)},J_{\gamma(0)}) \xrightarrow{\sim} (\mathcal{S}_{\gamma(1)},\omega_{\gamma(1)},D_{\gamma(1)},J_{\gamma(1)})\, ,
\end{equation*}
which covers the isometry
$T_\gamma:(E_{\gamma(0)},h_{\gamma(0)})\rightarrow (E_{\gamma(1)},
h_{\gamma(1)})$, i.e. the following diagram commutes:
\begin{equation*}
\scalebox{1.2}{
	\xymatrix{
(\mathcal{S}_{\gamma(0)},\omega_{\gamma(0)},D_{\gamma(0)},J_{\gamma(0)}) ~~\ar[d]_{\pi_{\gamma(0)}} \ar[r]^{\!\!\!\!\!\!\mathbf{T}_{\gamma}} & ~~ (\mathcal{S}_{\gamma(1)},\omega_{\gamma(1)},D_{\gamma(1)},J_{\gamma(1)}) \ar[d]^{\pi_{\gamma(1)}}\\
(E_{\gamma(0)},h_{\gamma(0)})  \ar[r]^{T_{\gamma}} & (E_{\gamma(1)}, h_{\gamma(1)}) \\
	}} 
\end{equation*}

The {\em extended holonomy group} of $\boldsymbol{\mathcal{D}}$ at the point $m\in M$ is the
subgroup of $\mathrm{Aut}(\mathcal{D}_m)$ defined through:
\begin{equation*}
\mathbb{G}_m\stackrel{{\rm def.}}{=} \{\mathbf{T}_{\gamma}\,|\, \gamma\in \mathcal{P}(M) , \gamma(0)=\gamma(1)=m\}\subset \mathrm{Aut}(\mathcal{D}_m)\, .
\end{equation*}

This gives commutative diagrams:
\begin{equation} \scalebox{1.2}{
\xymatrix{
			\boldsymbol{\mathcal{S}}_\alpha
			~~\ar[d] \ar[r]^{\!\!\!\!\!\!\mathbf{q}_\alpha} &
			~~\boldsymbol{\mathcal{S}}^0_{\alpha} \ar[d]\\ E_\alpha
			~~\ar[d]_{\pi_\alpha} \ar[r]^{\!\!\!\!\!\!q_\alpha}
			& ~~E^0_{\alpha} \ar[d]^{\pi^0_{\alpha}}\\
			U_\alpha \ar[r]^{\mathrm{id}_{U_\alpha}} & U_\alpha \\
			}}
\end{equation}
which extend the diagrams \eqref{ltriv}.

\scalebox{1.2}{
\xymatrix{
			\boldsymbol{\mathcal{S}}_\alpha
			~~\ar[d] \ar[r]^{\!\!\!\!\!\!\mathbf{q}_\alpha} &
			~~\boldsymbol{\mathcal{S}}^0_{\alpha} \ar[d]\\ E_\alpha
			~~\ar[d]_{\pi_\alpha} \ar[r]^{\!\!\!\!\!\!q_\alpha}
			& ~~E^0_{\alpha} \ar[d]^{\pi^0_{\alpha}}\\
			U_\alpha \ar[r]^{\mathrm{id}_{U_\alpha}} & U_\alpha \\
			}}

Let:
\begin{equation*}
\mathbf{D}^{\mathrm{ad}}\colon \Gamma(E,End(\boldsymbol{\mathcal{S}}))\to \Omega^{1}(E,End(\boldsymbol{\mathcal{S}}))\, ,
\end{equation*}
be the connection induced by $\mathbf{D}$ on the endomorphism bundle
$End(\boldsymbol{\mathcal{S}})$ of $\boldsymbol{\mathcal{S}}$.

The \emph{fundamental bundle form} $\mathbf{\Theta}$ of $\boldsymbol{\mathcal{D}}$ is
the $End(\boldsymbol{\mathcal{S}})$-valued one-form defined on $E$ as follows:
\begin{equation*}
\mathbf{\Theta} \stackrel{{\rm def.}}{=} \mathbf{D}^{\mathrm{ad}} \mathbf{J} \in \Omega^{1}(E,End(\boldsymbol{\mathcal{S}}))\, .
\end{equation*}

The fact $\mathbf{J}$ is vertical together with the fact that the
decomposition $TE = H\oplus V$ is $h$-orthogonal implies that we have:
\begin{equation*}
\mathbf{\Theta} \in \Gamma(E, V^{\ast}\otimes End(\boldsymbol{\mathcal{S}}))\, .
\end{equation*}

The \emph{fundamental bundle field} $\mathbf{\Psi}$ of $\boldsymbol{\mathcal{D}}$ is
the $End(\boldsymbol{\mathcal{S}})$-valued vector field defined on $E$ as follows:
\begin{equation*}
\mathbf{\Psi} \stackrel{{\rm def.}}{=} \left(\sharp_{h}\otimes \mathrm{Id}_{End(\boldsymbol{\mathcal{S}})} \right)\circ D^{\mathrm{ad}} \mathbf{J} \in \Gamma(E,V\otimes End(\boldsymbol{\mathcal{S}}))\, .
\end{equation*}

We denote by $\Theta_{m}\stackrel{{\rm def.}}{=}
\mathbf{\Theta}|_{E_{m}}$ the restriction of $\mathbf{\Theta}$ to $E_{m}$, which is a
section of $V^{\ast}|_{E_{m}}\otimes End(\mathcal{S}_{m})$, namely:
\begin{equation*}
\Theta_{m} \in \Gamma(E_{m}, V^{\ast}|_{E_{m}}\otimes End(\mathcal{S}_{m}))\, .
\end{equation*}

Likewise, we define $\Psi_{m}\stackrel{{\rm def.}}{=} \mathbf{\Psi}|_{E_{m}}$, which is a
section of $V|_{E_{m}}\otimes End(\mathcal{S}_{m})$:
\begin{equation*}
\Psi_{m} \in \Gamma(E_{m}, V|_{E_{m}}\otimes End(\mathcal{S}_{m}))
\end{equation*}

Since $V\subset TE$ is the vertical integrable distribution integrated
by the fibers of $\pi\colon (E,h)\to (M,g)$ (which by assumption are
connected), we have $V|_{E_{m}} \simeq TE_{m}$ and we obtain:
\begin{equation*}
\Theta_{m} = \Omega^{1}(E_{m}, End(\mathcal{S}_{m}))\, , \qquad \Psi_{m}\in \mathfrak{X}(E_{m},End(\mathcal{S}_{m}))\, .
\end{equation*}

Equation \eqref{eq:isoTheta} follows from the following
computation\footnote{Equation \eqref{eq:isoPsi} can be proved
  similarly.}:
\begin{equation*}
\mathbf{T}_{\gamma} \cdot \Theta_{m_{0}} = \mathbf{T}_{\gamma}\cdot D^{\mathrm{ad}}_{m_{0}}(\mathbf{T}^{-1}_{\gamma}\cdot\mathbf{T}_{\gamma}\cdot J_{m_{0}}) = \mathbf{T}_{\gamma}\cdot D^{\mathrm{ad}}_{m_{0}}(\mathbf{T}^{-1}_{\gamma}\cdot J_{m}) = D^{\mathrm{ad}}_{m} J_{m} = \Theta_{m}\, ,
\end{equation*}
where we have used the fact that $\mathbf{T}_{\gamma}$ preserves $D_{m_{0}}$ and $D_{m}$, i.e.:
\begin{equation} D^{\mathrm{ad}}_{m}(\xi)  =  \mathbf{T}_{\gamma}\cdot D^{\mathrm{ad}}_{m_{0}} (\mathbf{T}^{-1}_{\gamma}\cdot\xi) = \mathbf{T}_{\gamma}\cdot D^{\mathrm{ad}}_{m_{0}} (\mathbf{T}^{-1}_{\gamma}\circ\xi \circ T_{\gamma})\, , \quad\forall\,\, \xi\in\Gamma(E_{m},\mathcal{S}_{m})\, ,
\end{equation}
as well as the relations:
\begin{eqnarray} & (\mathbf{T}_{\gamma}\cdot J_{m_{0}})(\xi) = \mathbf{T}_{\gamma}\cdot J_{m_{0}}(\mathbf{T}^{-1}_{\gamma}\cdot\xi) = \mathbf{T}_{\gamma}\cdot (J_{m_{0}} \circ\mathbf{T}^{-1}_{\gamma}\circ \xi \circ T_{\gamma}) \nonumber\\
& = \mathbf{T}_{\gamma}\circ (J_{m_{0}} \circ\mathbf{T}^{-1}_{\gamma}\circ \xi \circ T_{\gamma})\circ T^{-1}_{\gamma} = \mathbf{T}_{\gamma}\circ J_{m_{0}} \circ\mathbf{T}^{-1}_{\gamma}\circ \xi = J_{m}(\xi)\, ,
\end{eqnarray}
which hold for all $\xi\in \Gamma(E_{m},\mathcal{S}_{m})$. Notice that the
$\mathbf{T}_{\gamma}$-action symbols $``\cdot"$ and $``\circ"$ in equations
\eqref{eq:D0m} and \eqref{eq:J0m} have a different meaning depending
on the step and the sections involved. In equation \eqref{eq:D0m} we
have:
\begin{equation*}
D^{\mathrm{ad}}_{m_{0}} (\mathbf{T}^{-1}_{\gamma}\circ\xi \circ T_{\gamma}) \in \Omega^{1}(E_{m_{0}},\mathcal{S}_{m_{0}})
\end{equation*}
and evaluating on a vector field $X\in\mathfrak{X}(E_{m})$ we obtain:
\begin{equation*}
\iota_{X} D^{\mathrm{ad}}_{m}(\xi) = \mathbf{T}_{\gamma}\circ \left(\iota_{T^{-1}_{\gamma\ast}X} D^{\mathrm{ad}}_{m_{0}} (\mathbf{T}^{-1}_{\gamma}\circ\xi \circ T_{\gamma})\right)\circ T^{-1}_{\gamma}\in \Gamma(E_{m},\mathcal{S}_{m})\, .
\end{equation*}
Likewise, in the second step of equation \eqref{eq:J0m} we use:
\begin{equation*}
\mathbf{T}^{-1}_{\gamma}\cdot\xi = \mathbf{T}^{-1}_{\gamma}\circ \xi \circ T_{\gamma}\in \Gamma(E_{m_{0}},\mathcal{S}_{m_{0}}) \, , \quad \xi\in \Gamma(E_{m},\mathcal{S}_{m})\, ,
\end{equation*}
where $\mathbf{T}^{-1}_{\gamma}$ in the left hand side acts through
$``\cdot"$ as the isomorphism of modules:
\begin{equation*}
\mathbf{T}^{-1}_{\gamma}\colon \Gamma(E_{m},\mathcal{S}_m) \to \Gamma(E_{m_{0}},\mathcal{S}_{m_{0}})\, ,
\end{equation*}
whereas $\mathbf{T}^{-1}_{\gamma}$ in the right-hand-side acts through $``\circ"$
as composition with the unbased automorphism
$\mathbf{T}^{-1}_{\gamma}\colon \mathcal{S}_{m}\to \mathcal{S}_{m_{0}}$ of vector bundles
covering $T^{-1}_{\gamma}$.

Let $\boldsymbol{\mathcal{D}} = (\pi,\mathbf{\Phi},{\boldsymbol{\Xi}})$ be a scalar-electromagnetic structure of
type:
\begin{equation*}
\mathcal{D} = (\mathcal{M}, \mathcal{G}, \Phi,\mathcal{S},D,\omega,J)
\end{equation*}
Then the isomorphism type of the fundamental bundle form $\mathbf{\Theta}$
of $\boldsymbol{\mathcal{D}}$ is given by:
\begin{equation*}
\Theta \stackrel{{\rm def.}}{=} \Theta_{m_{0}} = D^{\mathrm{ad}}J \in \Omega^{1}(\mathcal{M},End(\mathcal{S}))~~,
\end{equation*}
while the isomorphism type of the fundamental bundle field $\mathbf{\Psi}$
of $\boldsymbol{\mathcal{D}}$ is given by:
\begin{equation*}
\Psi \stackrel{{\rm def.}}{=} \Psi_{m_{0}} = \left(\sharp_{\mathcal{G}}\otimes \mathrm{Id}_{End(\mathcal{S})} \right) D^{\mathrm{ad}}J \in \mathfrak{X}(\mathcal{M},End(\mathcal{S})) \, .
\end{equation*}

Now let $s\in \Gamma(\pi)$ be a section of $\pi\colon (E,h)\to
(M,g)$. The pull-backs through $s$ of $\mathbf{\Phi}$ and $\mathbf{\Psi}$ satisfy:
\begin{equation*}
\mathbf{\Phi}^{s}\in \Gamma(M,(V^{\ast})^{s}\otimes End(\boldsymbol{\mathcal{S}}^{s}))\, , \qquad \mathbf{\Psi}^{s}\in \Gamma(E,V^{s}\otimes End(\boldsymbol{\mathcal{S}}^{s}))\, .
\end{equation*}

The {\em inner $g$-contraction of 2-tensors} is the bundle morphism
$\oslash_g:(\otimes^2T^\ast M)^{\otimes 2}\rightarrow\otimes^2 T^\ast
M$ uniquely determined by the condition:
\begin{equation*}
(\alpha_1\otimes\alpha_2)\oslash_g (\alpha_3\otimes \alpha_4)=(\alpha_2,\alpha_3)_g\alpha_1\otimes \alpha_4\, , \quad \forall\, \alpha_1, \alpha_2, \alpha_3, \alpha_4\in \Omega^1(M)\, .
\end{equation*}

Let $\boldsymbol{\mathcal{D}} = (\pi,\mathbf{\Phi},{\boldsymbol{\Xi}})$ be a scalar-electromagnetic bundle with
associated Kaluza-Klein space $\pi\colon (E,h)\to (M,g)$. The 
GESM theory associated to $\boldsymbol{\mathcal{D}}$ is defined by the following set of
partial differential equations on $(M,g)$:
\begin{itemize}
\item The Einstein equations\footnote{We denote Einstein's gravitational constant by $\kappa$.}:	
\begin{equation}
\mathcal{E}_{E}(g,s,\boldsymbol{\mathcal{V}}) \stackrel{{\rm def.}}{=} \mathrm{G}(g) -\kappa\,\mathrm{T}(g,s,\boldsymbol{\mathcal{V}}) = 0\, ,
\end{equation}
where $\mathrm{T}(g,s,\boldsymbol{\mathcal{V}})\in\Gamma(M,S^{2}T^{\ast}M)$ is the
energy-momentum tensor of the theory, which is given by:
\begin{equation*}
\mathrm{T}(g,s,\boldsymbol{\mathcal{V}})  = g\, e^{v}_{0}(g,h,s) - h^{s}_{V} + \frac{g}{2} \mathbf{\Phi}^{s}  + 2~\boldsymbol{\mathcal{V}} \bm{\oslash} \boldsymbol{\mathcal{V}} \, .
\end{equation*} 

\item The scalar equations:
\begin{equation} \mathcal{E}_{S}(g,s,\boldsymbol{\mathcal{V}}) \stackrel{{\rm def.}}{=} \tau^{v}(g,h,s) + (\mathrm{grad}_{h} \mathbf{\Phi})^{s}- \frac{1}{2} (\ast \boldsymbol{\mathcal{V}} , \mathbf{\Psi}^s\boldsymbol{\mathcal{V}}) = 0\, .
\end{equation}
\item The electromagnetic (or Maxwell) equations:
\begin{equation}
\mathcal{E}_{K}(g,s,\boldsymbol{\mathcal{V}}) \stackrel{{\rm def.}}{=}\mathrm{d}_{\mathbf{D}^s} \boldsymbol{\mathcal{V}}=0\, .
\end{equation}	

\end{itemize}

\noindent
with unknowns given by triples $(g,s,\boldsymbol{\mathcal{V}})\in \mathrm{Conf}_{\boldsymbol{\mathcal{D}}}(M)$.

The {\em solution sheaf} $\mathrm{Sol}_{\boldsymbol{\mathcal{D}}}$ of a GESM theory associated to
a scalar-electromagnetic bundle $\boldsymbol{\mathcal{D}} = (\pi,\mathbf{\Phi},{\boldsymbol{\Xi}})$ is the sheaf
of sets given by:
\begin{equation*}
\mathbf{Sol}_{\boldsymbol{\mathcal{D}}}(U)\stackrel{{\rm def.}}{=} \{(g,s,\boldsymbol{\mathcal{V}})\in \mathrm{Conf}_{\boldsymbol{\mathcal{D}}}(U) \,\, |\,\, \mathcal{E}_{E}(g,s,\boldsymbol{\mathcal{V}}) = 0\, , \quad  \mathcal{E}_{S}(g,s,\boldsymbol{\mathcal{V}}) = 0\, , \quad \mathcal{E}_{K}(g,s,\boldsymbol{\mathcal{V}}) = 0\}
\end{equation*}
for every open set $U\subset M$.

Let $\boldsymbol{\mathcal{D}} = (\pi,\mathbf{\Phi},{\boldsymbol{\Xi}})$ be an scalar-electromagnetic bundle of
type $\mathcal{D}=(\mathcal{M},\mathcal{S},\omega,D,J)$, whose Kaluza-Klein space is
integrable. Then any special trivializing atlas
$(U_\alpha,\mathbf{q}_\alpha)_{\alpha\in I}$ of $\boldsymbol{\mathcal{D}}$ induces bijections:
\begin{equation*}
\mathfrak{C}_\alpha \colon \mathbf{Conf}_{\boldsymbol{\mathcal{D}}}(U_{\alpha})\xrightarrow{\sim}  \mathrm{Conf}_{\mathcal{D}}(U_{\alpha})
\end{equation*}
which restrict bijections:
\begin{equation*}
\mathfrak{C}_\alpha \colon \mathbf{Sol}_{\boldsymbol{\mathcal{D}}}(U_{\alpha}) \xrightarrow{\sim} \mathrm{Sol}_{\mathcal{D}}(U_{\alpha})~~.
\end{equation*}

Let:
\begin{equation*}
g_\alpha\stackrel{{\rm def.}}{=} g|_{U_\alpha}~~,~~s_\alpha\stackrel{{\rm def.}}{=} s|_{U_\alpha}~~,~~\boldsymbol{\mathcal{V}}_\alpha\stackrel{{\rm def.}}{=} \boldsymbol{\mathcal{V}}|_{U_\alpha}~~
\end{equation*}
and $\mathfrak{C}_{\alpha}(g_{\alpha},s_{\alpha},\boldsymbol{\mathcal{V}}_{\alpha})=
(g_{\alpha},\varphi^\alpha,\mathcal{V}^\alpha)$.

Relations \eqref{cVlocdef}
imply the gluing conditions:
\begin{equation} \mathcal{V}^{\beta}|_{U_{\alpha\beta}}=\mathbf{f}_{\alpha\beta}^s \mathcal{V}^{\alpha}|_{U_{\alpha\beta}}~~,
\end{equation}
which accompany the gluing conditions \eqref{phigluing} for $\varphi^{\alpha}$ 
and the trivial gluing conditions:
\begin{equation} g_\alpha|_{U_{\alpha\beta}}=g_\beta|_{U_{\alpha\beta}}
\end{equation}
for $g_\alpha$.

Let $\pi:E\rightarrow M$ be a surjective submersion and $h$, $g$ be
pseudo-Riemannian metrics on $E$ and $M$ respectively. We say that
$\pi$ is a {\em pseudo-Riemannian submersion from} $(E,h)$ to $(M,g)$
if the following two conditions are satisfied:
\begin{enumerate}[1.]
\item $h$ is vertically non-degenerate with respect to $\pi$, i.e. the
  restriction of $h$ to $V$ is non-degenerate.
\item The based isomorphism $(\mathrm{d}\pi)_H:H\stackrel{\sim}{\rightarrow}
  (TM)^\pi$ is an isometry from $(H,h_H)$ to $((TM)^\pi,g^\pi)$.
\end{enumerate}

The {\em Kaluza-Klein correspondence} of $\pi$ is the map
$\mathcal{K}_\pi:\mathrm{Met}(M)\times \mathrm{Met}(V)\times\mathcal{H}(\pi)\rightarrow
\mathrm{Met}_\pi(E)$ defined through:
\begin{equation*}
\mathcal{K}_\pi(g,\mathfrak{h},H)\stackrel{{\rm def.}}{=} h_{g,\mathfrak{h},H}\in \mathrm{Met}_{\pi,g}(E)\subset \mathrm{Met}_\pi(E)\, .
\end{equation*}

Setting
$f:=(f_\mu^{~\nu})_{\mu,\nu=0\ldots 3}\stackrel{{\rm def.}}{=}
e^{-1}\in \mathcal{C}^\infty(W,\mathrm{Mat}(4,\mathbb{R}))$, we have
$f_{\mu}^{~\nu}e_{\nu}^{~\rho}=e_{\mu}^{~\nu}f_\nu^{~\rho}=\delta_\mu^{~\rho}$
and:
\begin{equation} \frac{\partial}{\partial u^\mu}=f_{\mu}^{~\nu}e_\nu-f_\mu^{~A} \frac{\partial}{\partial y^A}\, ,
\end{equation}
where we defined: 
\begin{equation*}
